import { GameData } from '../../Core/Data/GameData';
import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import { Plane } from '../Entity/Plane';
import { Boss } from '../Entity/Boss';
import { BATTLE_EVENT } from '../BattleEvents';
import { BOSS_CONFIG } from '../Config/BossConfig';
import type { EnemyType, SpawnSide } from '../Config/LevelConfig';

export class EnemySpawnSystem implements System {

    private _world: World = null!;

    onStart(world: World): void {
        this._world = world;
        world.bus.on(BATTLE_EVENT.ENEMY_SPAWN_REQUEST, this._onSpawnEnemy, this);
        world.bus.on(BATTLE_EVENT.BOSS_SPAWN_REQUEST, this._onSpawnBoss, this);
    }

    onDestroy(world: World): void {
        world.bus.off(BATTLE_EVENT.ENEMY_SPAWN_REQUEST, this._onSpawnEnemy, this);
        world.bus.off(BATTLE_EVENT.BOSS_SPAWN_REQUEST, this._onSpawnBoss, this);
        this._world = null!;
    }

    onTick(_world: World, _dt: number): void {
        // 事件驱动，无需每帧
    }

    private _onSpawnEnemy(enemyType: EnemyType, spawnSide: SpawnSide): void {
        const plane = new Plane('enemy');
        this._setSpawnPosition(plane, spawnSide);
        plane.originX = plane.x;
        plane.originY = plane.y;
        plane.collisionRadius = 20;
        this._configureEnemy(plane, enemyType, spawnSide);
        this._world.add(plane);
    }

    private _setSpawnPosition(plane: Plane, side: SpawnSide): void {
        const halfW = GameData.viewW / 2;
        const halfH = GameData.viewH / 2;

        if (side === 'left') {
            plane.x = -halfW - 30;
            plane.y = -halfH * 0.6 + Math.random() * halfH * 0.6;
            plane.moveDirX = 1;
            plane.moveDirY = 0;
        } else if (side === 'right') {
            plane.x = halfW + 30;
            plane.y = -halfH * 0.6 + Math.random() * halfH * 0.6;
            plane.moveDirX = -1;
            plane.moveDirY = 0;
        } else {
            plane.x = -halfW + Math.random() * GameData.viewW;
            plane.y = halfH + 30;
            plane.moveDirX = 0;
            plane.moveDirY = -1;
        }
    }

    private _configureEnemy(plane: Plane, type: EnemyType, side: SpawnSide): void {
        switch (type) {
            case 'sine':
                plane.hp = 25;
                plane.maxHp = 25;
                plane.moveSpeed = 120;
                plane.movePattern = 'sine';
                plane.moveFrequency = 3;
                plane.moveAmplitude = 80;
                break;
            case 'basic':
            default:
                plane.hp = 30;
                plane.maxHp = 30;
                plane.moveSpeed = 100;
                plane.movePattern = (side === 'top' && Math.random() < 0.5) ? 'sine' : 'straight';
                break;
        }

        plane.weapons.push({
            config: {
                fireInterval: 2.0,
                bulletType: 'yellow',
                bulletSpeed: 200,
                bulletDamage: 8,
                fireDirX: 0,
                fireDirY: -1,
            },
            cooldownTimer: Math.random() * 2.0,
            enabled: true,
        });
    }

    private _onSpawnBoss(bossId: string): void {
        const config = BOSS_CONFIG[bossId];
        if (!config) {
            console.warn(`[EnemySpawnSystem] 未知 Boss: ${bossId}`);
            return;
        }
        const boss = new Boss(config);
        boss.x = 0;
        boss.y = GameData.viewH / 2 - 300;
        this._world.add(boss);
        this._world.bus.emit(BATTLE_EVENT.BOSS_SPAWNED, config.name);
    }
}